import { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2.45.0";
import { customisationSummary } from "./customisation.ts";
import { getWarehouse } from "./warehouse.ts";

// Customer GST tax invoices and return invoices for one boutique part of an
// order (vendor_order). The boutique is the seller: they are issued in its
// legal name and GSTIN, generated by AllBoutiqs on its behalf, and never
// change once issued - seller, buyer and tax details are snapshotted.
//
// Tax invoice
// * Number: the boutique's own series, new every financial year:
//   AB0001/2627/0001 (next_boutique_invoice_number).
// * Prices include GST. Each product's rate comes from its category's HSN
//   code (gst_rate_for, which applies the apparel/footwear price band);
//   each line carries its share of the coupon as checkout recorded it (only
//   the lines the coupon was for); older orders share the order's discount
//   across all lines by value. Each boutique's invoice shows its share.
// * Same state (boutique's GSTIN state = delivery state) -> CGST + SGST,
//   otherwise IGST.
// * Shipping is part of the goods' supply: taxed at the rate of the
//   invoice's main (highest-value) product, under its HSN.
// * Warehouse route: billed to the customer, shipped to the AllBoutiqs
//   warehouse - the goods leave the boutique on this invoice (agreed with the
//   CA for the e-way bill, Nov 2026).
// * One sale invoice per part, issued when the goods leave the boutique (Ship
//   Now) or on first request. If the sale is undone before the customer has
//   the goods (a full return invoice: RTO, failed inspection, cancelled) and
//   the part is sent again, it goes on a new "replacement" invoice. An
//   exchange's replacement goes on its own "exchange" invoice.
//
// Return invoice (AB0001R2627/0001): takes back the returned items of a tax
// invoice at their invoiced value, or all of it when the sale is undone.
// Cancelled when the goods go back to the customer after all (a return that
// failed inspection, an RTO parcel sent again).

const round2 = (n: number) => Math.round(n * 100) / 100;

// A problem with the order's data that someone has to fix - shown as is.
export class InvoiceError extends Error {
  status: number;
  constructor(message: string, status = 422) {
    super(message);
    this.status = status;
  }
}

interface Line {
  line_no: number;
  order_item_id: string | null;
  description: string;
  hsn_code: string | null;
  size: string | null;
  color: string | null;
  sku: string | null;
  quantity: number;
  unit_price: number;
  discount: number;
  taxable_value: number;
  gst_rate: number;
  cgst_amount: number;
  sgst_amount: number;
  igst_amount: number;
  total: number;
}

function splitTax(amountInclusive: number, rate: number, intraState: boolean) {
  const taxable = round2(amountInclusive / (1 + rate / 100));
  const tax = round2(amountInclusive - taxable);
  const cgst = intraState ? round2(tax / 2) : 0;
  const sgst = intraState ? round2(tax - cgst) : 0;
  return { taxable, cgst, sgst, igst: intraState ? 0 : tax, total: round2(amountInclusive) };
}

// Reasons that undo the whole sale (the invoice no longer stands).
export const FULL_REVERSAL_REASONS = ["rto", "qc_failed", "order_cancelled", "replacement_returned"];

async function withLines(supabase: SupabaseClient, invoice: any) {
  const { data: lines } = await supabase.from("invoice_lines").select("*").eq("invoice_id", invoice.id).order("line_no");
  return { invoice, lines: lines ?? [] };
}

async function reversedInvoiceIds(supabase: SupabaseClient, invoiceIds: string[]): Promise<Set<string>> {
  if (!invoiceIds.length) return new Set();
  const { data } = await supabase
    .from("return_invoices")
    .select("invoice_id")
    .in("invoice_id", invoiceIds)
    .eq("status", "issued")
    .in("reason", FULL_REVERSAL_REASONS);
  return new Set((data ?? []).map((r) => r.invoice_id));
}

// The part's sale / replacement invoices, newest first, marked reversed or not.
async function partInvoices(supabase: SupabaseClient, vendorOrderId: string) {
  const { data, error } = await supabase
    .from("invoices")
    .select("*")
    .eq("vendor_order_id", vendorOrderId)
    .in("purpose", ["sale", "replacement"])
    .order("issued_at", { ascending: false });
  if (error) throw error;
  const reversed = await reversedInvoiceIds(supabase, (data ?? []).map((i) => i.id));
  return (data ?? []).map((invoice) => ({ invoice, reversed: reversed.has(invoice.id) }));
}

// The invoice the part's goods currently stand on, if any.
export async function currentInvoice(supabase: SupabaseClient, vendorOrderId: string) {
  const standing = (await partInvoices(supabase, vendorOrderId)).find((i) => !i.reversed);
  return standing ? withLines(supabase, standing.invoice) : null;
}

// For showing: the standing invoice, or else the newest one (a cancelled
// part still shows the invoice its return invoice takes back).
export async function findInvoice(supabase: SupabaseClient, vendorOrderId: string) {
  const all = await partInvoices(supabase, vendorOrderId);
  const pick = all.find((i) => !i.reversed) ?? all[0];
  return pick ? withLines(supabase, pick.invoice) : null;
}

// The part's standing invoice, issued now if there is none. Callers decide
// whether it may be issued yet (generate-invoice: paid / goods on their way;
// Ship Now: the goods are leaving the boutique).
export async function ensureInvoice(
  supabase: SupabaseClient,
  vendorOrderId: string,
): Promise<{ invoice: any; lines: any[]; created: boolean }> {
  const all = await partInvoices(supabase, vendorOrderId);
  const standing = all.find((i) => !i.reversed);
  if (standing) return { ...(await withLines(supabase, standing.invoice)), created: false };
  return issueInvoice(supabase, vendorOrderId, { purpose: all.length ? "replacement" : "sale" });
}

// The invoice an exchange's replacement from this boutique travels on.
export async function ensureExchangeInvoice(
  supabase: SupabaseClient,
  returnRequestId: string,
  vendorOrderId: string,
): Promise<{ invoice: any; lines: any[]; created: boolean }> {
  const { data: existing } = await supabase
    .from("invoices")
    .select("*")
    .eq("vendor_order_id", vendorOrderId)
    .eq("return_request_id", returnRequestId)
    .eq("purpose", "exchange")
    .order("issued_at", { ascending: false });
  const reversed = await reversedInvoiceIds(supabase, (existing ?? []).map((i) => i.id));
  const standing = (existing ?? []).find((i) => !reversed.has(i.id));
  if (standing) return { ...(await withLines(supabase, standing)), created: false };

  const { data: rr } = await supabase.from("return_requests").select("items").eq("id", returnRequestId).single();
  const items = ((rr?.items ?? []) as any[]).map((i) => ({
    orderItemId: String(i.order_item_id),
    quantity: Number(i.quantity ?? 1),
    size: i.exchange_to?.size ?? null,
    color: i.exchange_to?.color ?? null,
  }));
  return issueInvoice(supabase, vendorOrderId, { purpose: "exchange", returnRequestId, items });
}

interface ItemPick {
  orderItemId: string;
  quantity: number;
  size?: string | null; // an exchange's new size / colour
  color?: string | null;
}

async function issueInvoice(
  supabase: SupabaseClient,
  vendorOrderId: string,
  opts: { purpose: "sale" | "replacement" | "exchange"; returnRequestId?: string; items?: ItemPick[] },
): Promise<{ invoice: any; lines: any[]; created: boolean }> {
  const { data: vendorOrder, error: voErr } = await supabase
    .from("vendor_orders")
    .select("id, order_id, vendor_id, shipping_cost")
    .eq("id", vendorOrderId)
    .maybeSingle();
  if (voErr) throw voErr;
  if (!vendorOrder) throw new InvoiceError("Order item not found", 404);

  const { data: order, error: orderErr } = await supabase
    .from("orders")
    .select("id, created_at, customer_name, shipping_address, subtotal, discount_code, discount_amount, fulfilment_route, warehouse_id")
    .eq("id", vendorOrder.order_id)
    .single();
  if (orderErr) throw orderErr;

  // ---------- seller (boutique) ----------
  const [{ data: vendor, error: vendorErr }, { data: kyc }] = await Promise.all([
    supabase.from("vendors").select("name, gst_number, pan_number, address").eq("id", vendorOrder.vendor_id).single(),
    supabase.from("vendor_kyc").select("legal_business_name, pan, gstin").eq("vendor_id", vendorOrder.vendor_id).maybeSingle(),
  ]);
  if (vendorErr) throw vendorErr;
  const gstin: string | null = kyc?.gstin ?? vendor.gst_number ?? null;
  if (!gstin) throw new InvoiceError("This boutique has no GSTIN on file - an admin needs to add it before invoicing");
  const sellerStateCode = gstin.slice(0, 2);
  const { data: sellerState } = await supabase.from("indian_states").select("name").eq("gst_code", sellerStateCode).maybeSingle();

  // ---------- buyer / place of supply ----------
  const billingAddress = (order.shipping_address ?? {}) as Record<string, string>;
  const { data: posCode } = await supabase.rpc("gst_state_code", { _state: billingAddress.state ?? "" });
  if (!posCode) {
    throw new InvoiceError(`Delivery state "${billingAddress.state ?? ""}" isn't recognised - an admin needs to correct the address`);
  }
  const { data: posState } = await supabase.from("indian_states").select("name").eq("gst_code", posCode).maybeSingle();
  const intraState = posCode === sellerStateCode;

  const shipTo =
    order.fulfilment_route === "warehouse" && order.warehouse_id ? await getWarehouse(supabase, order.warehouse_id) : null;

  // ---------- lines ----------
  const { data: orderItems, error: itemsErr } = await supabase
    .from("order_items")
    .select("id, product_id, product_title, variant_title, size, color, sku, quantity, price, discount_amount, customisation")
    .eq("vendor_order_id", vendorOrder.id)
    .order("created_at");
  if (itemsErr) throw itemsErr;
  if (!orderItems?.length) throw new InvoiceError("No items found for this order", 400);

  // Whole part, or the items picked (an exchange) at the quantity picked.
  const picks = opts.items
    ? opts.items
        .map((p) => ({ pick: p, item: orderItems.find((i) => i.id === p.orderItemId) }))
        .filter((x): x is { pick: ItemPick; item: (typeof orderItems)[number] } => !!x.item)
    : orderItems.map((item) => ({ pick: null as ItemPick | null, item }));
  if (!picks.length) throw new InvoiceError("None of these items are from this boutique", 400);

  const productIds = [...new Set(picks.map((p) => p.item.product_id))];
  const { data: products } = await supabase
    .from("products")
    .select("id, categories(name, hsn_codes(id, code))")
    .in("id", productIds);
  const productById = new Map((products ?? []).map((p: any) => [String(p.id), p]));

  const itemsGross = round2(orderItems.reduce((s, i) => s + Number(i.price) * i.quantity, 0));
  const orderGross = Number(order.subtotal) || itemsGross;
  const orderDiscount = Number(order.discount_amount) || 0;

  const lines: Line[] = [];
  for (const [idx, { pick, item }] of picks.entries()) {
    const product = productById.get(String(item.product_id));
    const hsn = product?.categories?.hsn_codes;
    if (!hsn?.id) {
      const where = product?.categories?.name ? `category "${product.categories.name}"` : `"${item.product_title}" (no category)`;
      throw new InvoiceError(`No HSN code for ${where} - set it in Admin > Categories before invoicing`);
    }
    const quantity = pick ? Math.min(pick.quantity, item.quantity) : item.quantity;
    const fullGross = Number(item.price) * item.quantity;
    const fullDiscount =
      item.discount_amount != null
        ? Number(item.discount_amount)
        : orderGross > 0
          ? round2((orderDiscount * fullGross) / orderGross)
          : 0;
    const gross = Number(item.price) * quantity;
    const discount = round2((fullDiscount * quantity) / item.quantity);
    const { data: rate, error: rateErr } = await supabase.rpc("gst_rate_for", {
      _hsn_code_id: hsn.id,
      _unit_price: (gross - discount) / quantity,
    });
    if (rateErr) throw rateErr;
    const t = splitTax(gross - discount, Number(rate), intraState);
    const size = pick?.size ?? item.size;
    const color = pick?.color ?? item.color;
    lines.push({
      line_no: idx + 1,
      order_item_id: item.id,
      description:
        (item.variant_title && !pick?.size && !pick?.color ? `${item.product_title} (${item.variant_title})` : item.product_title) +
        (opts.purpose === "exchange" ? " - exchange replacement" : "") +
        (item.customisation ? ` - Customised: ${customisationSummary(item.customisation)}` : ""),
      hsn_code: hsn.code,
      size,
      color,
      sku: item.sku,
      quantity,
      unit_price: Number(item.price),
      discount,
      taxable_value: t.taxable,
      gst_rate: Number(rate),
      cgst_amount: t.cgst,
      sgst_amount: t.sgst,
      igst_amount: t.igst,
      total: t.total,
    });
  }

  // The delivery charge was for the whole part - not on an exchange.
  const shipping = opts.purpose === "exchange" ? 0 : Number(vendorOrder.shipping_cost) || 0;
  if (shipping > 0) {
    const main = [...lines].sort((a, b) => b.total - a.total)[0];
    const t = splitTax(shipping, main.gst_rate, intraState);
    lines.push({
      line_no: lines.length + 1,
      order_item_id: null,
      description: "Shipping charges",
      hsn_code: main.hsn_code,
      size: null,
      color: null,
      sku: null,
      quantity: 1,
      unit_price: shipping,
      discount: 0,
      taxable_value: t.taxable,
      gst_rate: main.gst_rate,
      cgst_amount: t.cgst,
      sgst_amount: t.sgst,
      igst_amount: t.igst,
      total: t.total,
    });
  }

  const sum = (k: keyof Line) => round2(lines.reduce((s, l) => s + Number(l[k]), 0));
  const issuedAt = new Date();
  const { data: invoiceNumber, error: numErr } = await supabase.rpc("next_boutique_invoice_number", {
    _vendor_id: vendorOrder.vendor_id,
    _at: issuedAt.toISOString(),
  });
  if (numErr) throw numErr;

  const { data: invoice, error: insertErr } = await supabase
    .from("invoices")
    .insert({
      invoice_number: invoiceNumber,
      vendor_order_id: vendorOrder.id,
      order_id: order.id,
      vendor_id: vendorOrder.vendor_id,
      purpose: opts.purpose,
      return_request_id: opts.returnRequestId ?? null,
      issued_at: issuedAt.toISOString(),
      order_number: `#${order.id.slice(0, 8).toUpperCase()}`,
      order_date: order.created_at,
      subtotal: round2(lines.filter((l) => l.order_item_id).reduce((s, l) => s + l.unit_price * l.quantity, 0)),
      shipping_cost: shipping,
      discount_code: order.discount_code,
      discount_amount: sum("discount"),
      taxable_value: sum("taxable_value"),
      cgst_amount: sum("cgst_amount"),
      sgst_amount: sum("sgst_amount"),
      igst_amount: sum("igst_amount"),
      tax_amount: round2(sum("cgst_amount") + sum("sgst_amount") + sum("igst_amount")),
      total: sum("total"),
      supply_type: intraState ? "intra_state" : "inter_state",
      seller_name: vendor.name,
      seller_legal_name: kyc?.legal_business_name ?? vendor.name,
      seller_gstin: gstin,
      seller_pan: kyc?.pan ?? vendor.pan_number ?? gstin.slice(2, 12),
      seller_address: vendor.address,
      seller_state: sellerState?.name ?? null,
      seller_state_code: sellerStateCode,
      billing_name: order.customer_name,
      billing_address: order.shipping_address,
      billing_state: posState?.name ?? billingAddress.state ?? null,
      place_of_supply_code: posCode,
      ship_to_name: shipTo?.name ?? null,
      ship_to_address: shipTo?.address ?? null,
    })
    .select("*")
    .single();
  if (insertErr) {
    // The sale invoice issued at the same moment by another request (two
    // clicks) - use that one.
    if ((insertErr as { code?: string }).code === "23505" && opts.purpose === "sale") {
      const raced = await currentInvoice(supabase, vendorOrderId);
      if (raced) return { ...raced, created: false };
    }
    throw insertErr;
  }

  const { error: linesErr } = await supabase.from("invoice_lines").insert(lines.map((l) => ({ ...l, invoice_id: invoice.id })));
  if (linesErr) {
    await supabase.from("invoices").delete().eq("id", invoice.id);
    throw linesErr;
  }

  return { invoice, lines, created: true };
}

// ---------- return invoices ----------

export type ReturnReason = "customer_return" | "exchange_return" | "rto" | "qc_failed" | "order_cancelled" | "replacement_returned";

// The boutique's return invoice taking back an invoice - the given items at
// the given quantity, or all of it. Issued once per invoice, reason and
// return request; asking again returns the same one.
export async function issueReturnInvoice(
  supabase: SupabaseClient,
  p: {
    invoiceId: string;
    reason: ReturnReason;
    returnRequestId?: string | null;
    items?: { orderItemId: string; quantity: number }[];
  },
): Promise<{ returnInvoice: any; lines: any[]; created: boolean }> {
  let existingQuery = supabase
    .from("return_invoices")
    .select("*")
    .eq("invoice_id", p.invoiceId)
    .eq("reason", p.reason)
    .eq("status", "issued");
  existingQuery = p.returnRequestId ? existingQuery.eq("return_request_id", p.returnRequestId) : existingQuery.is("return_request_id", null);
  const { data: existing } = await existingQuery.maybeSingle();
  if (existing) {
    const { data: lines } = await supabase.from("return_invoice_lines").select("*").eq("return_invoice_id", existing.id).order("line_no");
    return { returnInvoice: existing, lines: lines ?? [], created: false };
  }

  const { data: invoice, error: invErr } = await supabase.from("invoices").select("*").eq("id", p.invoiceId).single();
  if (invErr) throw invErr;
  const { data: invoiceLines } = await supabase.from("invoice_lines").select("*").eq("invoice_id", p.invoiceId).order("line_no");

  // Each taken-back line at the invoiced value for the quantity taken back.
  const taken = (invoiceLines ?? []).flatMap((l: any) => {
    if (!p.items) return [{ line: l, quantity: Number(l.quantity) }];
    if (!l.order_item_id) return []; // the delivery charge stays with the sale
    const pick = p.items.find((i) => i.orderItemId === l.order_item_id);
    return pick ? [{ line: l, quantity: Math.min(pick.quantity, Number(l.quantity)) }] : [];
  });
  if (!taken.length) throw new InvoiceError(`None of these items are on invoice ${invoice.invoice_number}`, 400);

  const lines = taken.map(({ line, quantity }, idx) => {
    const share = quantity / Number(line.quantity);
    const part = (v: number) => round2(Number(v) * share);
    return {
      line_no: idx + 1,
      order_item_id: line.order_item_id,
      description: line.description,
      hsn_code: line.hsn_code,
      size: line.size,
      color: line.color,
      quantity,
      unit_price: Number(line.unit_price),
      discount: part(line.discount),
      taxable_value: part(line.taxable_value),
      gst_rate: Number(line.gst_rate),
      cgst_amount: part(line.cgst_amount),
      sgst_amount: part(line.sgst_amount),
      igst_amount: part(line.igst_amount),
      total: part(line.total),
    };
  });
  const sum = (k: keyof (typeof lines)[number]) => round2(lines.reduce((s, l) => s + Number(l[k]), 0));

  const issuedAt = new Date().toISOString();
  const { data: number, error: numErr } = await supabase.rpc("next_boutique_document_number", {
    _vendor_id: invoice.vendor_id,
    _doc_kind: "return_invoice",
    _at: issuedAt,
  });
  if (numErr) throw numErr;

  const { data: returnInvoice, error: insertErr } = await supabase
    .from("return_invoices")
    .insert({
      return_invoice_number: number,
      invoice_id: invoice.id,
      vendor_order_id: invoice.vendor_order_id,
      order_id: invoice.order_id,
      vendor_id: invoice.vendor_id,
      return_request_id: p.returnRequestId ?? null,
      reason: p.reason,
      issued_at: issuedAt,
      taxable_value: sum("taxable_value"),
      cgst_amount: sum("cgst_amount"),
      sgst_amount: sum("sgst_amount"),
      igst_amount: sum("igst_amount"),
      total: sum("total"),
    })
    .select("*")
    .single();
  if (insertErr) {
    if ((insertErr as { code?: string }).code === "23505") return issueReturnInvoice(supabase, p);
    throw insertErr;
  }
  const { error: linesErr } = await supabase
    .from("return_invoice_lines")
    .insert(lines.map((l) => ({ ...l, return_invoice_id: returnInvoice.id })));
  if (linesErr) {
    await supabase.from("return_invoices").delete().eq("id", returnInvoice.id);
    throw linesErr;
  }
  return { returnInvoice, lines, created: true };
}

// The goods are going back to the customer after all.
export async function cancelReturnInvoices(
  supabase: SupabaseClient,
  filter: { returnRequestId?: string; vendorOrderIds?: string[]; reasons: ReturnReason[] },
  cancelReason: string,
) {
  let q = supabase
    .from("return_invoices")
    .update({ status: "cancelled", cancelled_at: new Date().toISOString(), cancel_reason: cancelReason })
    .eq("status", "issued")
    .in("reason", filter.reasons);
  if (filter.returnRequestId) q = q.eq("return_request_id", filter.returnRequestId);
  if (filter.vendorOrderIds) q = q.in("vendor_order_id", filter.vendorOrderIds);
  const { data, error } = await q.select("id");
  if (error) throw error;
  return (data ?? []).map((r) => r.id as string);
}

// A part's sale undone before the customer had the goods: the return invoice
// taking back its standing invoice (none if it was never invoiced).
export async function reverseCurrentInvoice(
  supabase: SupabaseClient,
  vendorOrderId: string,
  reason: "rto" | "qc_failed" | "order_cancelled",
) {
  const current = await currentInvoice(supabase, vendorOrderId);
  if (!current) return null;
  return (await issueReturnInvoice(supabase, { invoiceId: current.invoice.id, reason })).returnInvoice;
}
